(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-642":{scenario:{company:"Truc Lam Urban Planning Studio",supervisor:{name:"Lương Thu Hà",role:{vi:"Trưởng phòng Quy hoạch & GIS",en:"Head of Planning & GIS"}},ref_code:"QH-2618",title:{vi:"Đúng hệ tọa độ. Đúng chỉ tiêu. Đúng quy hoạch.",en:"Right datum. Right indicators. Right plan."},brief:{vi:"Bạn kiểm tra hồ sơ đề xuất dự án QH-2618 cho một lô đất hỗn hợp tại Hà Nội. Lô đất có tổng diện tích 2400 m2, trong đó 300 m2 nằm trong chỉ giới đường đỏ của tuyến đường quy hoạch; quy hoạch chi tiết 1/500 đã duyệt cho hệ số sử dụng đất tối đa 3,5. Ranh lô do tư vấn nộp được số hóa ở hệ WGS84. Đối chiếu phiếu kiểm tra nháp với tài liệu gốc, sửa hệ tọa độ nộp hồ sơ và tổng diện tích sàn tối đa (m2), rồi lập báo cáo có căn cứ.",en:"You are checking project proposal QH-2618 for a mixed-use plot in Hanoi. The plot covers 2400 m2 in total, of which 300 m2 lies inside the red line of a planned road; the approved 1/500 detailed plan allows a maximum floor area ratio of 3.5. The consultant digitized the plot boundary in WGS84. Compare the draft checklist with the source documents, correct the submission coordinate system and the maximum gross floor area (m2), then write an evidence-based report."},reference_title:{vi:"Quy định dữ liệu & bản đồ QHCT 1/500 đã duyệt",en:"Data rules & approved 1/500 detailed plan"},fields:[{id:"CRS",label:{vi:"Hệ tọa độ dữ liệu nộp",en:"Submission coordinate system"},initial:"WGS84-UTM48N",expected:"VN2000-TM3-105",choices:["WGS84-UTM48N","VN2000-TM3-105","VN2000-UTM48"],reference:"Quy định nộp dữ liệu GIS",ref_value:{vi:"Hệ VN-2000, múi chiếu 3 độ, kinh tuyến trục 105°00' cho Hà Nội (mã nội bộ VN2000-TM3-105)",en:"VN-2000 datum, 3-degree zone, central meridian 105°00' for Hanoi (internal code VN2000-TM3-105)"},hint:{vi:"Dữ liệu địa chính, quy hoạch cấp tỉnh dùng VN-2000 múi 3 độ với kinh tuyến trục riêng của tỉnh.",en:"Provincial cadastral and planning data use VN-2000 in a 3-degree zone with the province's own central meridian."}},{id:"GFA_MAX",label:{vi:"Tổng diện tích sàn tối đa (m2)",en:"Maximum gross floor area (m2)"},initial:"8400",expected:"7350",reference:"Bảng chỉ tiêu lô đất HH-04",ref_value:{vi:"Tổng diện tích 2400 m2; trong chỉ giới đường đỏ 300 m2; hệ số sử dụng đất tối đa 3,5",en:"Total area 2400 m2; inside the red line 300 m2; maximum FAR 3.5"},hint:{vi:"Phần đất nằm trong chỉ giới đường đỏ dành cho đường, không được tính vào diện tích lô khi áp chỉ tiêu.",en:"Land inside the red line is reserved for the road and is excluded from the plot area when applying indicators."}}],sop32:{vi:"Tổng diện tích sàn tối đa = diện tích lô đất trong phạm vi quy hoạch (đã trừ phần nằm trong chỉ giới đường đỏ) x hệ số sử dụng đất tối đa theo quy hoạch chi tiết đã duyệt.",en:"Maximum gross floor area = plot area within the plan boundary (after removing land inside the red line) x the maximum floor area ratio of the approved detailed plan."},context:{label:"GIS / QH-2618",metrics:[{label:{vi:"Tổng diện tích lô",en:"Total plot area"},value:"2400 m2"},{label:{vi:"Trong chỉ giới đường đỏ",en:"Inside the red line"},value:"300 m2"},{label:{vi:"Hệ số sử dụng đất tối đa",en:"Maximum FAR"},value:"3.5"},{label:{vi:"Tỷ lệ bản đồ quy hoạch",en:"Plan map scale"},value:"1/500"}]},crisis:{vi:"Đại diện chủ đầu tư gọi: “Em cứ tính trên 2400 m2, bao giờ mở đường mới thu hồi. Nhờ em dịch ranh lô trên lớp GIS ra 2 m phía đường cho khớp bản vẽ. Bên anh có quà cảm ơn.”",en:"The developer's representative calls: “Just use 2400 m2, the road land will only be taken when the road is built. Please shift the plot boundary 2 m toward the road in the GIS layer to match our drawing. We have a thank-you gift for you.”"},options:{safe:{vi:"Từ chối quà và yêu cầu sai, giữ ranh theo dữ liệu đo đạc, tính trên 2100 m2, báo Trưởng phòng bằng văn bản và hướng dẫn chủ đầu tư thủ tục điều chỉnh quy hoạch hợp lệ.",en:"Decline the gift and the request, keep the surveyed boundary, compute on 2100 m2, report to the Head of Planning in writing and point the developer to the lawful plan amendment process."},shortcut:{vi:"Dịch ranh 2 m và tính trên 2400 m2 cho kịp tiến độ, sau này có sai thì điều chỉnh.",en:"Shift the boundary 2 m and compute on 2400 m2 to stay on schedule, adjusting later if needed."},wait:{vi:"Treo hồ sơ, không phản hồi chủ đầu tư và chờ ai đó quyết thay.",en:"Park the file, ignore the developer and wait for someone else to decide."}},questions:{vi:["Vì sao dữ liệu phải ở hệ VN2000-TM3-105 và ranh lô lệch thế nào khi chồng lớp WGS84 lên nền quy hoạch?","Trình bày cách tính 7350 m2 và rủi ro pháp lý nếu tính trên toàn bộ 2400 m2."],en:["Why must the data be in VN2000-TM3-105, and how does the boundary shift when a WGS84 layer is overlaid on the planning base?","Explain how you reached 7350 m2 and the legal risk of using the full 2400 m2."]},hints:{vi:["Đọc quy định nộp dữ liệu GIS: hệ quy chiếu, múi chiếu và kinh tuyến trục của địa phương.","Tách phần đất trong chỉ giới đường đỏ trước khi nhân hệ số sử dụng đất ở SOP mục 3.2.","Đọc lại SOP mục 4.2: không nhận quà, không sửa dữ liệu không gian theo yêu cầu của bên được thẩm định."],en:["Read the GIS submission rules: datum, zone width and the local central meridian.","Remove the land inside the red line before applying the FAR in SOP 3.2.","Re-read SOP 4.2: accept no gifts and never alter spatial data at the request of the party under review."]}},learning:{summary:{vi:"Chuyên viên quy hoạch đô thị và GIS xây dựng, quản lý cơ sở dữ liệu không gian phục vụ lập, thẩm định và quản lý quy hoạch. Người làm nghề số hóa bản đồ, kiểm soát hệ tọa độ, tính toán chỉ tiêu sử dụng đất, phân tích hạ tầng, dân số và môi trường để tham mưu quyết định. Nghề đòi hỏi chính xác về dữ liệu, hiểu pháp luật quy hoạch và giữ liêm chính trước áp lực lợi ích.",en:"An urban planning and GIS specialist builds and manages the spatial database used to prepare, review and administer urban plans. The role digitizes maps, controls coordinate systems, calculates land-use indicators and analyses infrastructure, population and environment to support decisions. It requires precise data, sound knowledge of planning law and integrity under pressure from vested interests."},responsibilities:{vi:["Xây dựng, cập nhật cơ sở dữ liệu GIS quy hoạch: ranh lô, chức năng sử dụng đất, chỉ giới, hạ tầng.","Kiểm tra hệ tọa độ, độ chính xác và siêu dữ liệu của dữ liệu do tư vấn, đơn vị đo đạc nộp.","Tính toán, đối chiếu chỉ tiêu: mật độ xây dựng, hệ số sử dụng đất, tầng cao, dân số, chỗ đỗ xe.","Phân tích không gian về giao thông, ngập úng, bán kính phục vụ công trình công cộng.","Lập bản đồ chuyên đề, báo cáo thẩm định và cung cấp thông tin quy hoạch cho tổ chức, cá nhân."],en:["Build and update the planning GIS: plot boundaries, land-use functions, building lines and infrastructure.","Check the coordinate system, accuracy and metadata of data submitted by consultants and surveyors.","Calculate and cross-check indicators: site coverage, FAR, height, population and parking.","Run spatial analysis on transport, flooding and service radii of public facilities.","Produce thematic maps and review reports and provide planning information to the public."]},competencies:[{name:{vi:"Hệ quy chiếu & trắc địa",en:"Datums & geodesy"},desc:{vi:"Hiểu VN-2000, WGS84, múi chiếu 3 độ và 6 độ, chuyển đổi tọa độ đúng tham số.",en:"Understand VN-2000, WGS84, 3-degree and 6-degree zones and transform coordinates with correct parameters."}},{name:{vi:"Phân tích không gian",en:"Spatial analysis"},desc:{vi:"Chồng lớp, tạo vùng đệm, phân tích mạng lưới và thống kê theo ô lô để trả lời câu hỏi quy hoạch.",en:"Overlay, buffer, run network analysis and plot-level statistics to answer planning questions."}},{name:{vi:"Chỉ tiêu quy hoạch",en:"Planning indicators"},desc:{vi:"Tính đúng mật độ xây dựng, hệ số sử dụng đất, tầng cao và kiểm tra theo quy chuẩn.",en:"Calculate site coverage, FAR and height correctly and check them against the national code."}},{name:{vi:"Quản trị dữ liệu",en:"Data governance"},desc:{vi:"Chuẩn hóa thuộc tính, siêu dữ liệu, phiên bản và phân quyền để dữ liệu tin cậy, truy vết được.",en:"Standardize attributes, metadata, versions and access so the data is trusted and traceable."}},{name:{vi:"Liêm chính công vụ",en:"Public-service integrity"},desc:{vi:"Không nhận quà, không chỉnh dữ liệu theo lợi ích riêng; minh bạch căn cứ khi tham mưu.",en:"Accept no gifts, never bend data for private interests and keep the basis of advice transparent."}}],knowledge:{vi:["Luật Quy hoạch đô thị và nông thôn cùng các nghị định, thông tư hướng dẫn hiện hành.","QCVN 01:2021/BXD về quy hoạch xây dựng: mật độ xây dựng, hệ số sử dụng đất, khoảng lùi.","Hệ quy chiếu và hệ tọa độ quốc gia VN-2000, kinh tuyến trục theo từng tỉnh, thành phố.","Các cấp độ quy hoạch: quy hoạch chung, phân khu 1/2000 (1/5000) và chi tiết 1/500.","Chuẩn dữ liệu địa lý: siêu dữ liệu ISO 19115, dịch vụ bản đồ OGC WMS/WFS.","Khái niệm chỉ giới đường đỏ, chỉ giới xây dựng và hành lang bảo vệ hạ tầng kỹ thuật."],en:["The Law on Urban and Rural Planning with its current implementing decrees and circulars.","QCVN 01:2021/BXD on construction planning: site coverage, FAR and setbacks.","The national VN-2000 datum and coordinate system with each province's central meridian.","Planning levels: general plan, zoning plan 1/2000 (1/5000) and detailed plan 1/500.","Geographic data standards: ISO 19115 metadata and OGC WMS/WFS map services.","Red line, building line and technical infrastructure protection corridors."]},tools:["QGIS","ArcGIS Pro","PostgreSQL / PostGIS","AutoCAD / MicroStation","Máy thu GNSS RTK","Phần mềm chuyển đổi tọa độ VN-2000"],kpis:{vi:["Tỷ lệ hồ sơ thẩm định đúng hạn và không phải trả lại do sai số liệu.","Độ lệch vị trí trung bình của dữ liệu nộp so với nền chuẩn (mục tiêu dưới ngưỡng cho phép).","Tỷ lệ lớp dữ liệu có siêu dữ liệu đầy đủ và cập nhật.","Số khiếu nại về thông tin quy hoạch do sai dữ liệu (mục tiêu bằng 0)."],en:["Share of reviews completed on time without being returned for data errors.","Average positional offset of submitted data against the reference base (below tolerance).","Share of data layers with complete, current metadata.","Complaints about planning information caused by data errors (target zero)."]},day:[{time:"08:00",vi:"Kiểm tra hồ sơ mới nộp, hệ tọa độ và siêu dữ liệu của từng lớp dữ liệu.",en:"Check new submissions, coordinate systems and metadata for each layer."},{time:"09:30",vi:"Chồng lớp ranh lô lên nền quy hoạch đã duyệt, đánh dấu sai lệch vị trí.",en:"Overlay plot boundaries on the approved plan base and flag positional offsets."},{time:"11:00",vi:"Tính chỉ tiêu mật độ xây dựng, hệ số sử dụng đất và lập bảng đối chiếu.",en:"Calculate site coverage and FAR and build the comparison table."},{time:"14:00",vi:"Họp với tư vấn thiết kế, giải thích yêu cầu chỉnh sửa có dẫn căn cứ.",en:"Meet the design consultant and explain required changes with references."},{time:"16:00",vi:"Cập nhật cơ sở dữ liệu, xuất bản đồ chuyên đề và hoàn thiện báo cáo thẩm định.",en:"Update the database, export thematic maps and finalize the review report."}],mistakes:{vi:["Nhận dữ liệu WGS84 hoặc sai kinh tuyến trục mà không chuyển đổi, gây lệch ranh lô.","Tính hệ số sử dụng đất trên cả phần đất nằm trong chỉ giới đường đỏ.","Chỉnh ranh hoặc chỉ tiêu theo yêu cầu của chủ đầu tư mà không có quyết định điều chỉnh quy hoạch."],en:["Accepting WGS84 data or the wrong central meridian without transformation, shifting plot boundaries.","Applying the FAR to land that lies inside the red line.","Changing boundaries or indicators at a developer's request without an approved plan amendment."]},career:[{vi:"Kỹ thuật viên GIS / số hóa bản đồ",en:"GIS technician / map digitizer"},{vi:"Chuyên viên quy hoạch & GIS",en:"Urban planning & GIS specialist"},{vi:"Chủ trì đồ án quy hoạch / Trưởng nhóm dữ liệu không gian",en:"Lead planner / Spatial data team lead"},{vi:"Giám đốc quy hoạch & đô thị thông minh",en:"Director of planning & smart city"}],glossary:[{term:"VN-2000",vi:"Hệ quy chiếu và hệ tọa độ quốc gia của Việt Nam dùng cho đo đạc, bản đồ địa chính và quy hoạch.",en:"Vietnam's national datum and coordinate system for surveying, cadastral mapping and planning."},{term:"Hệ số sử dụng đất (FAR)",vi:"Tỷ số giữa tổng diện tích sàn công trình và diện tích lô đất.",en:"Ratio of a building's gross floor area to the plot area."},{term:"Mật độ xây dựng",vi:"Tỷ lệ diện tích chiếm đất của công trình trên tổng diện tích lô đất.",en:"Share of the plot area covered by the building footprint (site coverage)."},{term:"Chỉ giới đường đỏ",vi:"Đường ranh giới phân định phần đất dành cho đường giao thông, hạ tầng với phần đất xây dựng.",en:"Boundary line separating land reserved for roads and infrastructure from buildable land."},{term:"Kinh tuyến trục",vi:"Kinh tuyến gốc của múi chiếu; mỗi tỉnh dùng một kinh tuyến trục riêng trong VN-2000 múi 3 độ.",en:"The central meridian of a projection zone; each province has its own in VN-2000 3-degree zones."}],quiz:[{q:{vi:"Lô đất 1800 m2, trong đó 200 m2 nằm trong chỉ giới đường đỏ, hệ số sử dụng đất 4,0. Tổng diện tích sàn tối đa là bao nhiêu?",en:"A 1800 m2 plot has 200 m2 inside the red line and a FAR of 4.0. What is the maximum gross floor area?"},options:{vi:["7200 m2","6400 m2","8000 m2","1600 m2"],en:["7200 m2","6400 m2","8000 m2","1600 m2"]},answer:1,explain:{vi:"Diện tích tính chỉ tiêu = 1800 - 200 = 1600 m2; 1600 x 4,0 = 6400 m2.",en:"Indicator area = 1800 - 200 = 1600 m2; 1600 x 4.0 = 6400 m2."}},{q:{vi:"Dữ liệu quy hoạch cấp tỉnh thường phải nộp ở hệ tọa độ nào?",en:"Which coordinate system is usually required for provincial planning data?"},options:{vi:["WGS84 kinh độ, vĩ độ","WGS84 UTM múi 6 độ","Hệ tọa độ giả định của tư vấn","VN-2000 múi 3 độ, kinh tuyến trục của tỉnh"],en:["WGS84 latitude and longitude","WGS84 UTM 6-degree zone","The consultant's local grid","VN-2000 3-degree zone with the province's central meridian"]},answer:3,explain:{vi:"Bản đồ địa chính và quy hoạch tỷ lệ lớn dùng VN-2000 múi 3 độ với kinh tuyến trục của từng tỉnh.",en:"Large-scale cadastral and planning maps use VN-2000 3-degree zones with each province's central meridian."}},{q:{vi:"Chủ đầu tư đề nghị dịch ranh lô trên GIS và tặng quà cảm ơn. Bạn làm gì?",en:"A developer asks you to shift a plot boundary in the GIS and offers a gift. What do you do?"},options:{vi:["Từ chối, giữ dữ liệu đo đạc và báo cáo bằng văn bản","Nhận quà nhưng không dịch ranh","Dịch ranh vì sai lệch nhỏ","Im lặng và để hồ sơ tồn đọng"],en:["Refuse, keep the surveyed data and report in writing","Take the gift but leave the boundary","Shift it since the gap is small","Stay silent and let the file stall"]},answer:0,explain:{vi:"Nhận quà và sửa dữ liệu theo lợi ích riêng vi phạm liêm chính công vụ; phải từ chối và báo cáo.",en:"Taking gifts or bending data breaches public integrity; refuse and report."}},{q:{vi:"Mật độ xây dựng được tính như thế nào?",en:"How is site coverage calculated?"},options:{vi:["Tổng diện tích sàn / diện tích lô","Số tầng x diện tích lô","Diện tích chiếm đất của công trình / diện tích lô","Diện tích cây xanh / diện tích lô"],en:["Gross floor area / plot area","Number of floors x plot area","Building footprint / plot area","Green area / plot area"]},answer:2,explain:{vi:"Mật độ xây dựng là tỷ lệ diện tích chiếm đất của công trình trên diện tích lô; tổng sàn / lô là hệ số sử dụng đất.",en:"Site coverage is footprint over plot area; gross floor area over plot area is the FAR."}}],tools_en:["QGIS","ArcGIS Pro","PostgreSQL / PostGIS","AutoCAD / MicroStation","GNSS RTK receiver","VN-2000 coordinate transformation software"]}}})})(window.KKR);
